import { interactionChoice, meetingShell } from './interaction-ui-v40.js';
import { innkeeper } from './hospitality-v36.js';
import { renderAvatar } from './avatar.js';
import { inventoryEntries } from './inventory-ui.js';
import { renderCarriedArt } from './item-art.js';
import { tradeInventory, quoteTrade, shopAccessReason, tradeMerchant } from './trading.js';
import { equipmentComparator } from './gear-comparison.js';
import { renderEquipmentComparison } from './equipment-comparison-ui.js';

const greeting={generous:'Come in from the road. Take a look, and we will see what you can spare.',exacting:'Good tools deserve a careful eye. Set your goods on the counter and I will weigh the price.',secretive:'A quiet customer is welcome. Tell me what you need for the road.',gregarious:'There you are. Roads bring stories, but a good pair of boots brings you home.',wary:'Keep your belongings where we can both see them. Now, what do you need?',ambitious:'A small counter for now. One day I will have a house full of these goods. What can I find for you?'};
export function currentShopSession(s,session){if(session?.vendor==='inn'&&!innkeeper(s)?.here)return null;const m=tradeMerchant(s,session?.vendor||'market');return session?.merchantId===m?.id&&session?.locationId===s.locationId?session:null;}
export function renderMerchantMeeting(s,r,ui){
 const {e,button}=ui,vendor=r.kind==='materials'?'materials':r.subjectId||'market',session=currentShopSession(s,ui.shopSession),reason=shopAccessReason(s,vendor),mode=session?.mode||'dialogue',terms=mode==='terms';
 if(mode==='trade')return `<section class="service-meeting merchant-meeting">${renderTradeTable(s,session,ui)}</section>`;
 const line=terms?'I buy unequipped gear and honestly recovered treasure. Choose what you want and what you can offer; coins settle the difference.':vendor==='materials'?'I sell ore, cloth, timber, stone, hide and crystal in bundles of three. Choose one bundle per trade; collecting it takes one day. The work steward handles commissions.':vendor==='apothecary'?'Looking for a remedy? I have healing potions. They restore Health, though an illness still needs a doctor.':vendor==='outfitter'?'Heading out? I keep rations and camping kits. Take a look before you leave.':greeting[r.person.disposition]||greeting.wary;
 const choices=interactionChoice(ui,{label:'“What Are You Selling?”',op:'shop-browse',description:'Browse their stock and offer your own goods.',disabledReason:reason})+(terms?'':interactionChoice(ui,{label:'“What Would You Take in Trade?”',op:'shop-terms'}))+interactionChoice(ui,{label:'“Perhaps Another Time.”',op:'shop-leave',quiet:true});
 return meetingShell(s,r,ui,{className:'merchant-meeting',backLabel:'← Back to the Market',speech:'“'+line+'”',choices});
}

export function renderTradeTable(s,session,ui){
 const {e,button}=ui,v=tradeInventory(s,session.vendor||'market'),draft=session.draft,q=quoteTrade(s,draft),selection=session.selected||'',side=selection.startsWith('sell:')?'sell':'buy',id=selection.slice(side.length+1);
 const carried=inventoryEntries(s),sell=carried.map(r=>({...r,...v.sell.find(i=>i.id===r.id),disabledReason:v.sell.find(i=>i.id===r.id)?.disabledReason||(!v.sell.some(i=>i.id===r.id)?'This shop does not trade for this belonging.':null)}));
 const selected=(side==='sell'?sell:v.buy).find(i=>i.id===id),count=(which,key)=>draft[which].find(i=>i.id===key)?.quantity||0;
 const matches=r=>(session.filter||'all')==='all'||r.kind===session.filter;
 const query=String(session.query||'').trim().toLowerCase(),visible=rows=>rows.filter(r=>matches(r)&&(!query||r.name.toLowerCase().includes(query)));
 const grid=(rows,which)=>{const shown=visible(rows);return `<div class="trade-item-grid" role="group" aria-label="${which==='buy'?'Shopkeeper Stock':'Your Carried Items'}">${shown.map(r=>`<button type="button" class="trade-cell rarity-${r.item?.quality||'common'} ${r.disabledReason?'untradeable':''} ${selection===which+':'+r.id?'selected':''}" data-op="shop-item" data-id="${e(which+':'+r.id)}" aria-pressed="${selection===which+':'+r.id}" aria-label="${e(r.name+' · '+(r.disabledReason||r.price+' Gold')+(count(which,r.id)?' · '+count(which,r.id)+' Offered':''))}">${renderCarriedArt(r,e)}<span class="trade-item-name">${e(r.name)}</span><small>${r.disabledReason?'—':r.price+'g'}${r.quantity>1?' · ×'+r.quantity:''}</small>${count(which,r.id)?`<span class="trade-count">${count(which,r.id)}</span>`:''}</button>`).join('')}</div>${shown.length?'':'<p class="small-copy">No items match this view.</p>'}`;};
 const quantityButton=(which,r,increase,{inspector=false}={})=>`<button type="button" class="button ${inspector?'secondary':'ghost'} small" data-op="${increase?'shop-add':'shop-remove'}" data-id="${e(which+':'+r.id)}" aria-label="${e((increase?'Increase':'Decrease')+' '+(which==='buy'?'buy':'sell')+' quantity for '+r.name+' by one'+(session.vendor==='materials'&&which==='buy'?' bundle':''))}" ${(increase&&(Boolean(r.disabledReason)||count(which,r.id)>=(which==='buy'?v.buy:v.sell).find(i=>i.id===r.id)?.quantity))?'disabled':''}>${inspector?(which==='buy'?'Request One':'Offer One'):increase?'+':'−'}</button>`;
 const offer=(which,rows)=>`<div class="trade-offer" aria-label="${which==='buy'?'Goods Requested':'Goods Offered'}"><h4>${which==='buy'?'You Receive':'You Offer'}</h4>${rows.length?rows.map(r=>`<div class="trade-offer-row"><span>${e(r.name)} <small>×${r.quantity} · ${r.price*r.quantity}g</small></span>${quantityButton(which,r,false)}${quantityButton(which,r,true)}</div>`).join(''):'<p class="small-copy">Choose items from this inventory.</p>'}</div>`;
 const inspector=selected?`<section class="trade-inspector" aria-label="Selected Item">${renderCarriedArt(selected,e)}<div><h3 id="trade-item-heading" tabindex="-1">${e(selected.name)}</h3><p>${e(selected.description||'A carried belonging.')}</p><p>${selected.disabledReason?e(selected.disabledReason):`${side==='buy'?'Asking Price':'Offered Credit'}: <strong>${selected.price} Gold</strong> · ${side==='buy'?(selected.kind==='materials'?'3 Units per Bundle · 1 Day to Collect':(selected.stock||selected.quantity)+' in stock'):selected.quantity+' carried'}`}</p>${selected.item?`<p class="small-copy">${Object.entries(selected.item.bonuses).filter(([,n])=>n).map(([k,n])=>e(k[0].toUpperCase()+k.slice(1))+' '+(n>0?'+':'')+n).join(' · ')}</p>${side==='buy'?`<details class="trade-comparison"><summary>Equipment Changes</summary>${renderEquipmentComparison(equipmentComparator(s)(selected.item.id),ui,{purchase:true})}</details>`:''}`:''}</div>${quantityButton(side,selected,true,{inspector:true})}</section>`:'<p class="trade-inspect-help">Choose an item to inspect it, then add it to the table.</p>';
 return `<div class="trade-workspace"><header class="trade-heading"><div class="trade-merchant">${renderAvatar(v.merchant,{size:'small',age:v.merchant.age})}<div><span class="eyebrow">ACROSS THE COUNTER</span><h3 id="trade-heading" tabindex="-1">Trade with ${e(v.merchant.name)}</h3></div></div><div>${button('Back to Conversation','shop-conversation','','ghost small')}</div></header><form id="shop-search" class="trade-toolbar"><label class="sr-only" for="shop-query">Search Both Inventories</label><input id="shop-query" name="query" type="search" placeholder="Search Both Inventories" value="${e(session.query||'')}"><label>Show<select name="category">${[['all','All Goods'],['equipment','Equipment'],['supplies','Supplies'],['materials','Materials'],['loot','Treasure']].map(([key,name])=>`<option value="${key}" ${key===(session.filter||'all')?'selected':''}>${name}</option>`).join('')}</select></label><button type="submit" class="button secondary small">Find</button></form><div class="trade-inventories"><section><div class="section-heading"><h4>${e(v.merchant.name)}’s Stock</h4><span class="small-copy">${session.vendor==='inn'?'Food &amp; Drink':session.vendor==='materials'?'3 Units per Bundle':'Season '+(v.merchant.season+1)}</span></div>${grid(v.buy,'buy')}${offer('buy',q.buy)}</section><section><div class="section-heading"><h4>Your Inventory</h4><span class="inventory-gold">${s.hero.gold} Gold</span></div>${grid(sell,'sell')}${offer('sell',q.sell)}</section></div>${inspector}<footer class="trade-settlement"><div class="trade-totals"><span>Goods Requested <strong>${q.buyTotal}g</strong></span><span>Your Goods <strong>${q.sellTotal}g</strong></span><span>${q.goldDue<0?'You Receive':'You Pay'} <strong>${Math.abs(q.goldDue)} Gold</strong></span><span>Gold After Trade <strong>${q.goldAfter}g</strong></span>${session.vendor==='materials'?`<span>Collection Time <strong>${q.days} Day${q.days===1?'':'s'}</strong></span>`:''}</div><div class="trade-confirm">${button('Confirm Trade','shop-confirm','','primary',Boolean(q.disabledReason))}${button('Clear Offer','shop-clear','','ghost small',!draft.buy.length&&!draft.sell.length)}</div><p class="small-copy" role="status">${e(q.disabledReason||(session.vendor==='materials'?'Choose one bundle per trade: 3 units, 1 day to collect. Goods and coins exchange together on confirmation.':'Both sides exchange together. Nothing changes until you confirm.'))}</p></footer></div>`;
}
